parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-opus-5-5',
  max_tokens: 300,
  system: 'You qualify inbound sales leads. hot = clear buying intent (asks for price, call, demo, or gives budget/timeline). warm = interested but vague, no urgency. cold = spam, irrelevant, job seekers, or no intent. Always answer by calling the qualify_lead tool.',
  tools: [
    {
      name: 'qualify_lead',
      description: 'Record the qualification of a lead.',
      input_schema: {
        type: 'object',
        properties: {
          status: { type: 'string', enum: ['hot', 'warm', 'cold'] },
          reason: { type: 'string', description: 'One short sentence explaining the status.' }
        },
        required: ['status', 'reason']
      }
    }
  ],
  tool_choice: { type: 'tool', name: 'qualify_lead' },
  messages: [
    { role: 'user', content: 'Lead data:\n' + JSON.stringify($json.body) }
  ]
}) }}

parameters.jsCode:
const lead = $('Webhook').first().json.body ?? {};
const res = $input.first().json ?? {};
const tool = (res.content ?? []).find((c) => c.type === 'tool_use');
const q = tool?.input ?? {};
const ok = ['hot', 'warm', 'cold'].includes(q.status);

return [
  {
    json: {
      Timestamp: new Date().toISOString(),
      Name: lead.name ?? '',
      Phone: lead.phone ?? '',
      Email: lead.email ?? '',
      Source: lead.source ?? '',
      Message: lead.message ?? '',
      Status: ok ? q.status : 'warm',
      Reason: ok ? q.reason ?? '' : 'AI qualification failed - review manually',
    },
  },
];

